const projects=[{slug:'project-black',name:'Project Black',category:'Arts & culture / Exhibition',className:'black-art',description:'A Pan-African art exhibition and cultural experience celebrating African creativity, artistic expression, identity and culture.',organisation:'Client details to be confirmed',services:'Planning · Coordination · Exhibition delivery',art:'PROJECT<br>BLACK',label:'A celebration of African creativity'}, {slug:'lighting-threads',name:'Lighting Threads',category:'Fashion / Live experience',className:'threads-art',description:'A fashion-focused show delivered through SFC Fashion Connect, bringing creative expression and live experience together.',organisation:'SFC Fashion Connect / Esperanza Life Church',services:'Production · Logistics · Live execution',art:'Lighting<br>Threads',label:'Fashion. Expression. Connection.'}];
const capabilities=[['Project management','A clear plan. A shared direction.','Scope development, timelines, budget coordination, resource planning, stakeholder management, progress tracking and delivery oversight.'],['Project execution','Where the plan meets the real world.','On-ground coordination, production management, vendor and team coordination, implementation oversight and deliverable management.'],['Procurement & sourcing','The right resources, in the right place.','Product and material sourcing, supplier coordination, price and availability research, purchase coordination and delivery coordination.'],['Operations & logistics','Every moving part, accounted for.','Site coordination, transportation, scheduling, resource movement, operational planning and on-site support.']];
const steps=[['Understand','Get clear on the idea, the ambition and what success looks like.'],['Plan','Map the timelines, resources, responsibilities and deliverables.'],['Coordinate','Bring the people, partners and moving parts together.'],['Execute','Make it happen on the ground. Solve problems as they arise.'],['Deliver','Bring the project to completion, with the outcome in focus.']];
const eyebrow=t=>`<div class="eyebrow"><span class="dot"></span>${t}</div>`;
const art=p=>`<div class="art ${p.className}"><span class="art-label">${p.label}</span><div class="${p.slug==='project-black'?'orbit':'thread'}" aria-hidden="true"></div><strong>${p.art}</strong></div>`;
const card=p=>`<a class="project" href="#projects/${p.slug}">${art(p)}<div class="project-meta"><div><h3>${p.name}</h3><p>${p.category}</p></div><span class="circle-arrow" aria-hidden="true">↗</span></div></a>`;
const closing=()=>`<section class="closing">${eyebrow('The next project could be yours')}<h2>Big idea?<br>Let's get it done.</h2><a class="pill" href="#contact">Start a conversation <span>↗</span></a><span class="big-arrow" aria-hidden="true">↗</span></section>`;
const serviceList=()=>`<div class="services-list">${capabilities.map((c,i)=>`<details><summary><span>0${i+1}</span>${c[0]}<b aria-hidden="true">+</b></summary><p><strong>${c[1]}</strong><br>${c[2]}</p></details>`).join('')}</div>`;
const process=()=>`<div class="process">${steps.map((s,i)=>`<article><span class="eyebrow">0${i+1} ↗</span><h3>${s[0]}</h3><p>${s[1]}</p></article>`).join('')}</div>`;
function home(){return `<section class="hero"><div class="hero-top">${eyebrow('Project management & delivery')}<span class="eyebrow">Built on ideas. Driven by execution.</span></div><h1>Ideas are easy.<br><em>Making</em> it<br>happen is us.</h1><div class="star" aria-hidden="true"><i></i></div><div class="hero-bottom"><p>We bring the planning, people and moving parts together to turn ambitious ideas into things that actually happen.</p><a class="pill" href="#projects">Explore our work <span>↗</span></a><span class="scroll-note">A little less talk. A lot more done. ↓</span></div></section><div class="ticker" aria-hidden="true"><div>${Array(4).fill('From the first what if <b>✳</b> To the final we did it <b>✳</b> All the moving parts <b>✳</b> One clear outcome <b>✳</b>').join('')}</div></div><section class="section"><div class="section-top"><div>${eyebrow('01 / Selected work')}<h2>Proof, not promises.</h2></div><a class="text-link" href="#projects">All projects ↗</a></div><div class="projects">${projects.map(card).join('')}</div><p class="caption">Concept artwork shown. Project photography to follow.</p></section><section class="section statement"><div>${eyebrow('02 / The people behind the doing')}</div><div><h2>Great projects don't<br>happen by chance.<br>They happen <em>by design.</em></h2><p>Between an idea and its execution, there are a hundred moving parts. We bring structure to the complexity, keep everyone moving together, and get the work done.</p><a class="text-link" href="#about">Meet Progenius ↗</a></div></section><section class="section">${eyebrow('03 / What we bring')}<h2>Whatever it takes.<br>Every step of the way.</h2>${serviceList()}</section>${closing()}`;}
document.querySelector('.menu').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);});
const head=(label,title,text='')=>`<section class="page-head">${eyebrow(label)}<h1 class="page-title">${title}</h1>${text?`<p>${text}</p>`:''}</section>`;
function about(){return `${head('This is Progenius','We manage what it takes<br>to make things happen.','We exist for the space between an idea and its successful execution.')}<section class="section"><div class="copy-grid"><h2>Structure for<br>your ambition.</h2><div><p>A project is never just a plan. It is people, decisions, timelines, resources and the unexpected. Progenius brings those moving parts together and manages them towards a clear outcome.</p><p>We can join at the first conversation or at the point where your project needs experienced coordination and hands-on execution support.</p></div></div><div class="copy-grid"><h2>Different worlds.<br>The same commitment.</h2><div><p>From arts and culture to fashion, live experiences, corporate initiatives and community projects, our approach starts with understanding what needs to happen.</p><p>Our capabilities adapt to the project: planning, production, sourcing, logistics, people and delivery.</p></div></div><div class="copy-grid"><h2>How we show up.</h2><div><p><strong>Clarity.</strong> Everyone understands the objective and their part in it.</p><p><strong>Resourcefulness.</strong> We find practical ways through the unexpected.</p><p><strong>Ownership.</strong> We stay focused on execution and the final outcome.</p></div></div></section>${closing()}`;}
function services(){return `${head('Our capabilities','All the moving parts.<br>One team in your corner.','Support throughout the project lifecycle, from shaping the plan to coordinating its delivery.')}<section class="section">${serviceList()}</section><section class="section statement"><div>${eyebrow('The approach')}</div><div><h2>One clear path.<br>From <em>what if</em> to done.</h2><p>Every project is different. A shared process keeps the objective in sight.</p></div></section><section class="section">${process()}</section>${closing()}`;}
function work(){return `${head('Selected projects / 02','The work speaks.','Creative projects. Real-world complexity. Explore the projects behind the Progenius portfolio.')}<section class="section"><div class="projects">${projects.map(card).join('')}</div><p class="caption">Concept artwork shown. Project photography, dates and locations are awaiting confirmation.</p></section>${closing()}`;}
function caseStudy(p){const next=projects.find(q=>q.slug!==p.slug);return `${head(p.category,p.name,p.description)}<section class="section"><div class="case-art">${art(p)}</div><p class="caption">Concept artwork — not documentary project photography.</p><div class="case-info"><span><strong>Organisation</strong><br>${p.organisation}</span><span><strong>Focus</strong><br>${p.category}</span></div><div class="copy-grid"><h2>The project.</h2><p>${p.description}</p></div><div class="copy-grid"><h2>The delivery story.</h2><div><p>${p.slug==='project-black'?'The case study will explore Progenius’ involvement in planning, coordinating and delivering the exhibition.':'The case study will explore the coordination of creative production, people, schedules, vendors, logistics and live execution.'}</p><div class="notice">Full case study coming soon. The detailed scope, project timeline, responsibilities and outcomes are being confirmed before publication.</div></div></div><div class="copy-grid"><h2>Behind the scenes.</h2><p>Project photography and the complete process story will be added here once approved.</p></div><a class="text-link" href="#projects/${next.slug}">Next project: ${next.name} ↗</a></section>${closing()}`;}
function contact(){return `${head('Start something','Let’s build something.','Tell us what you’re working on and where you need support.')}<section class="section contact-grid"><div><h2>A big ambition.<br>A rough sketch.<br>A tricky brief.</h2><p>Every project starts somewhere.<br>Let’s start with yours.</p><div class="notice">Enquiry delivery is being set up. You can prepare and download your project brief here. Nothing is sent from this preview.</div></div><form id="enquiry"><div class="form-grid"><label>Your name *<input name="name" autocomplete="name" required maxlength="100"></label><label>Organisation<input name="organisation" autocomplete="organization" maxlength="150"></label><label>Email *<input name="email" autocomplete="email" type="email" required></label><label>Phone number<input name="phone" autocomplete="tel" type="tel"></label><label>Project type *<select name="type" required><option value="">Select project type</option><option>Arts & culture</option><option>Fashion</option><option>Events & experiences</option><option>Community</option><option>Corporate</option><option>Procurement</option><option>Something else</option></select></label><label>Project location<input name="location" placeholder="City / country"></label><label>Estimated timeline<input name="timeline" placeholder="When are you looking to deliver?"></label><label>Budget range (optional)<input name="budget" placeholder="Include your currency"></label><label class="full">Services required<select name="services"><option>Help me work out what I need</option>Project management</option>Project execution</option>Procurement & sourcing</option>Operations & logistics</option>End-to-end support</option></select></label><label class="full">What are you planning? *<textarea name="description" required minlength="15" maxlength="5000" placeholder="The idea, the objective, and where we can help."></textarea></label><label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="pill" type="submit">Download project brief <span>↓</span></button><p class="form-note">Your details stay in this page and the file you download.</p><div id="form-status" role="status"></div></form></section>`;}
function render(){const route=location.hash.slice(1)||'home';const p=projects.find(p=>route===`projects/${p.slug}`);const views={home,about,services,projects:work,contact};document.querySelector('#app').innerHTML=p?caseStudy(p):views[route]?views[route]():`${head('Page not found','A small detour.')}<section class="section"><a class="pill" href="#home">Back to home ↗</a></section>`;document.title=`${p?p.name:({home:'From idea to execution.',about:'About',services:'Capabilities',projects:'Our work',contact:'Start a project'}[route]||'Page not found')} — Progenius`;document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${route}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0);const form=document.querySelector('#enquiry');if(form)form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);if(data.get('website'))return;const text='PROGENIUS — PROJECT BRIEF\n\n'+Array.from(data).filter(([k])=>k!=='website').map(([k,v])=>`${k.toUpperCase()}\n${v||'Not provided'}\n`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='progenius-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your project brief has been downloaded. No enquiry has been sent.';});}
window.addEventListener('hashchange',render);render();
